%[text] # Assess Regression Neural Network Performance
%[text] Create a feedforward regression neural network (NN) model with fully connected layers using `fitrnet`. Use validation data for early stopping of the training process to prevent overfitting the model. Then, use the object functions of the model to assess its performance on test data.
clc;
clearvars;
close all;

%including all parent folders up to the file 'code', this makes visible all
%files within this code
addingPathParentFolderByName('code'); %[output:16249859]

%running the simulation parameters
Parameters
%%
%[text] #### Load Sample Data
%[text] Load the dataset compiled in the `dataset.mlx` file. The Dataset file is accesible in the [IEEEDataPort repository at this link](https://dx.doi.org/10.21227/vv2r-qn28) after loggin or in the [Ocean Code portal (dataset folder) at this link](https://codeocean.com/capsule/6777864/tree/v1) `(withouth any loggin requirements).` You need to download the dataset first and place on this local folder.
load Dataset_cell2cell.mat
%[text] Regenerate the dataset in case parameters have changed in the `Parameters.mlx` file
%Dataset_compiler
%[text] Delete posible rows of the table in which the table has missing values.
Dataset = rmmissing(Dataset);
%%
%[text] #### Feature extraction
%Read the true distance among the cells
dist=table2array(Dataset(:,1));
%Read the vesicles released by the immune cell
sequence=table2array(Dataset(:,2:end));
%calculating the slope
window=2;
slope=sequence(:,window:end)-sequence(:,1:end-window+1);
%calculating the amplitude and location of peaks
[peak,loc]=min(slope,[],2);
%Conforming the new database
peakTime = (loc - 1) * dt0;
Dataset = array2table([dist, peakTime]);
% Dataset=array2table(horzcat(dist,peak,loc));
%%
%[text] #### Plotting
figure; %[output:6fb85591]
time=(0:length(sequence(1,:))-1)*dt0;
idx=1:20:50;
for i=idx
    plot(time/60,sequence(i,1:end),'LineWidth',2); grid on; hold on %[output:6fb85591]
end
xlabel('Time [min]','FontSize',fontsize,'Interpreter','latex'); %[output:6fb85591]
ylabel({'Released vesicles'},'FontSize',fontsize,'Interpreter','latex'); %[output:6fb85591]

legend({strcat('$d=',num2str(dist(idx(1))*10^6),'$'),... %[output:6fb85591]
        strcat('$d=',num2str(dist(idx(2))*10^6),'$'),... %[output:6fb85591]
        strcat('$d=',num2str(dist(idx(3))*10^6),'~\mu$m')},... %[output:6fb85591]
        'Interpreter','latex','Location','southwest','NumColumns',3); %[output:6fb85591]

set(gca,'FontSize',fontsize); %[output:6fb85591]
%Annotations
rectangle('Position',[0 485 15 25],'LineStyle','--','Curvature',0.2,'LineWidth',1.5); hold on; %[output:6fb85591]
h=annotation('arrow'); %[output:6fb85591]

%Embedded plot
set(h,'parent', gca, ... %[output:6fb85591]
    'position', [15 495 20 0], ... %[output:6fb85591]
    'HeadLength', 7, 'HeadWidth', 7, 'HeadStyle', 'plain', ... %[output:6fb85591]
    'Color', 'k', 'LineWidth', 1); %[output:6fb85591]
p = get(gca, 'Position');
h_2 = axes('Parent', gcf, 'Position', [p(1)+0.45 p(2)+0.45 p(3)-0.5 p(4)-0.5]); %[output:6fb85591]
total=500;
for i=ceil(linspace(1,length(dist),3))
    plot(time(1:total),(slope(i,1:total)),'LineWidth',2); grid on; hold on %[output:6fb85591]
end
% xlabel('Time [s]','FontSize',fontsize,'Interpreter','latex');
ylabel({'Slope'},'FontSize',fontsize,'Interpreter','latex'); %[output:6fb85591]
set(h_2,'FontSize',fontsize-1); %[output:6fb85591]

figure %[output:8e01953b]
plot(dist*1e6,peak*10^3,'LineWidth',2); grid on; %[output:8e01953b]
xlabel('Distance [$\mu$m]','Interpreter','latex'); %[output:8e01953b]
ylabel('Amplitude [$\times 10^3$]','Interpreter','latex'); %[output:8e01953b]
set(gca,'FontSize',fontsize+2); %[output:8e01953b]

yyaxis right %[output:8e01953b]
plot(dist*1e6,loc,'--o','LineWidth',2,'MarkerIndices',1:30:length(loc)); grid on; %[output:8e01953b]
ylabel('Time [s]','Interpreter','latex'); %[output:8e01953b]
set(gca,'FontSize',fontsize+2); %[output:8e01953b]

legend({'Minimum of the slope','Peak time'}); %[output:8e01953b]

%%
%[text] ## Partition Data
%[text] Split the data into training, validation, and test sets. First, reserve approximately one tenth of the observations for the test set. Then, split the remaining data in one tenth to create the validation and training sets.
rng("default") % For reproducibility of the data partitions
%Test dataset
cvp1 = cvpartition(size(Dataset,1),"Holdout",1/10);
testTbl = Dataset(test(cvp1),:);
%Validation dataset
remainingTbl = Dataset(training(cvp1),:);
cvp2 = cvpartition(size(remainingTbl,1),"Holdout",(3/10/(1-1/10)));
validationTbl = remainingTbl(test(cvp2),:);
%Train dataset
trainTbl = remainingTbl(training(cvp2),:);
%[text] ## Train Neural Network
%[text] Train a regression neural network model by using the training set. Specify the `Var1` column of `tblTrain` as the response variable, and standardize the numeric predictors. Evaluate the model at each iteration by using the validation set. Specify to display the training information at each iteration by using the `Verbose` name-value argument. By default, the training process ends early if the validation loss is greater than or equal to the minimum validation loss computed so far, six times in a row. To change the number of times the validation loss is allowed to be greater than or equal to the minimum, specify the `ValidationPatience` name-value argument.
% Mdl = fitrnet(trainTbl,"Var1","Standardize",true, ...
%     "ValidationData",validationTbl, 'ValidationPatience',10,...
%     "Verbose",1,...
%     "LayerSizes",[1],...
%     "Activations",'sigmoid','LossTolerance',1e-9);
%%
% Existing partitions: Var1 = distance [m], Var2 = peak time [s]
xTr = trainTbl.Var2;
yTr = trainTbl.Var1 * 1e6;
xVa = validationTbl.Var2;
yVa = validationTbl.Var1 * 1e6;
xTe = testTbl.Var2;
yTe = testTbl.Var1 * 1e6;

% Exact least-squares fit: distance_um = w * peakTime_s + b
theta = [xTr, ones(size(xTr))] \ yTr;
w = theta(1);
b = theta(2);
predLinear = w*xTe + b;

% Same sigmoid architecture, now trained on distances in micrometres
rng default
MdlUM = fitrnet(xTr,yTr, ...
    "Standardize",true, ...
    "ValidationData",{xVa,yVa}, ...
    "ValidationPatience",10, ...
    "LayerSizes",1, ...
    "Activations","sigmoid", ...
    "LossTolerance",1e-8);

predNN = predict(MdlUM,xTe);

fprintf('Linear: w = %.6g um/s, b = %.6g um\n',w,b); %[output:9e6e0fc2]
fprintf('Linear RMSE = %.6g um\n',sqrt(mean((predLinear-yTe).^2))); %[output:057dab9a]
fprintf('NN RMSE     = %.6g um\n',sqrt(mean((predNN-yTe).^2))); %[output:9e53ca4e]

figure; %[output:2e1c3ba4]
plot(yTe,predLinear,'o',yTe,predNN,'x',yTe,yTe,'k-'); %[output:2e1c3ba4]
grid on; axis equal; %[output:2e1c3ba4]
xlabel('True distance [\mum]'); %[output:2e1c3ba4]
ylabel('Predicted distance [\mum]'); %[output:2e1c3ba4]
legend('Linear wx+b','One sigmoid hidden neuron','Ideal', ... %[output:2e1c3ba4]
       'Location','best'); %[output:2e1c3ba4]
set(gca,'FontSize',fontsize) %[output:2e1c3ba4]
%%
% Visualize the network structure
net=fitnet(MdlUM.LayerSizes);
net.layers{1}.transferFcn='logsig';%corresponding to sigmoid within the Mdl object
view(net); %[output:726a6a2d]
%net.numWeightElements
%%
%[text] Use the information inside the `TrainingHistory` property of the object `Mdl` to check the iteration that corresponds to the minimum validation mean squared error (MSE). The final returned model `Mdl` is the model trained at this iteration.
iteration = MdlUM.TrainingHistory.Iteration;
valLosses = MdlUM.TrainingHistory.ValidationLoss;
[~,minIdx] = min(valLosses);
iteration(minIdx) %[output:2b16a741]
trainLosses = MdlUM.TrainingHistory.TrainingLoss;

figure; %[output:96a088fa]
fontsize=27;
semilogy(iteration,trainLosses,iteration,valLosses,'LineWidth',2); grid on; %[output:96a088fa]
legend(["Training","Validation"]) %[output:96a088fa]
xlabel("Iteration",'Interpreter','latex'); %[output:96a088fa]
ylabel("Mean Squared Error",'Interpreter','latex'); %[output:96a088fa]
set(gca,'FontSize',fontsize); %[output:96a088fa]
%[text] ## Evaluate Test Set Performance
%[text] Evaluate the performance of the trained model `Mdl` on the test set `testTbl` by using the `loss` and `predict` object functions.
%[text] Compute the test set mean squared error (MSE). Smaller MSE values indicate better performance.
% mse = loss(MdlUM,testTbl,"Var1")
%[text] Compare the predicted test set response values to the true response values. Plot the predicted distances along the vertical axis and the true distance along the horizontal axis. Points on the reference line indicate correct predictions. A good model produces predictions that are scattered near the line.

figure; %[output:6dcac8a6]
plot(testTbl.Var1*10^6,testTbl.Var1*10^6,'LineWidth',2,'MarkerIndices',1:20:length(dist)); %[output:6dcac8a6]
grid on %[output:6dcac8a6]
hold on %[output:6dcac8a6]
plot(testTbl.Var1*10^6,predNN,"--o",'LineWidth',2,'MarkerIndices',1:20:length(dist)); %[output:6dcac8a6]
hold off %[output:6dcac8a6]

xlabel('True distance [$\mu$m]','Interpreter','latex'); %[output:6dcac8a6]
ylabel('Predicted distance [$\mu$m]','Interpreter','latex'); %[output:6dcac8a6]
legend({'True distance','Predicted distance'},'Interpreter','latex','Location','northwest'); %[output:6dcac8a6]
set(gca,'FontSize',fontsize); %[output:6dcac8a6] %[output:35ae3800] %[output:826d5f0e]

%%
% ======================= Helper Functions =======================

function addingPathParentFolderByName(targetName)
    % Start from the current directory
    currFolder = pwd;
    found = false;
    
    % Continue searching until you reach the root folder
    while true
        % Get the parent folder
        [parentFolder, currentName] = fileparts(currFolder);
        
        % Check if the current folder's name is the target
        if strcmpi(currentName, targetName)
            found = true;
            break;
        end
        
        % If we've reached the root or no change, exit the loop
        if isempty(parentFolder) || strcmp(currFolder, parentFolder)
            break;
        end
        
        % Move one level up
        currFolder = parentFolder;
    end

    if found
        addpath(genpath(currFolder));
        fprintf('Adding matlab path to: %s\n', currFolder);
    else
        error('Folder named "%s" not found in any parent directory.', targetName);
    end
end
